import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Protocol Watchlist","description":"A collection of observation cards for agent protocols that have not yet met the canonical-chapter bar — three groups covering discovery/directory, payments/commerce, and web/interaction; each card records owner, canonical URL, status, and gaps, plus the promotion threshold and the discovery≠trust≠authorization rule.","frontmatter":{"title":"Protocol Watchlist","description":"A collection of observation cards for agent protocols that have not yet met the canonical-chapter bar — three groups covering discovery/directory, payments/commerce, and web/interaction; each card records owner, canonical URL, status, and gaps, plus the promotion threshold and the discovery≠trust≠authorization rule.","domain":"tech","tags":["tech","action","protocols","watchlist","landscape"],"navOrder":76,"topicId":"protocol-watchlist","layer":"7","status":"watchlist","nodeType":"resource","owner":"learn-ai","externalOwners":[],"prerequisites":["protocol-map"],"next":[],"specVersion":"Multi-protocol observation cards (each carries status and retrievedAt; unified sweep 2026-09-01)","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/07-interoperability/watchlist.md","filePath":"tech/07-interoperability/watchlist.md","lastUpdated":1791174142000}'),n={name:"tech/07-interoperability/watchlist.md"};function i(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<blockquote><p><strong>Group</strong>: Interoperability | <strong>Previous group exit</strong>: build a traceable retrieval chain with an update path | <strong>This group exit</strong>: on encountering any listed protocol, immediately state what it solves, who owns it, and which threshold it is missing <strong>Prerequisites</strong>: <a href="./">Protocol Map</a> | <strong>Next</strong>: protocols meeting the threshold get promoted to standalone canonical chapters</p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>BLUF</strong>: the agent protocol ecosystem ships faster than any tutorial can revision. This page is an <strong>observation-card collection</strong>, not a tutorial: each card answers &quot;full name, owner, canonical URL, status, boundary, and why it is not canonical yet&quot;. The cards sit in three groups — discovery and directory, payments and commerce, interaction and web.</p><p><strong>Structure declaration (simplified five-part)</strong>: this page&#39;s status is watchlist; the full &quot;Usage / Principles / Development&quot; sections are omitted and replaced by observation cards — reason: these candidates generally lack publicly versioned specification maturity and a runnable zero-key fixture; the Resource Library section is kept. Card facts are as of 2026-09-01.</p><h3 id="promotion-threshold-when-a-card-becomes-a-canonical-chapter" tabindex="-1">Promotion threshold (when a card becomes a canonical chapter) <a class="header-anchor" href="#promotion-threshold-when-a-card-becomes-a-canonical-chapter" aria-label="Permalink to &quot;Promotion threshold (when a card becomes a canonical chapter)&quot;">​</a></h3><p>All five must hold before promotion from the watchlist:</p><ol><li><strong>A publicly versioned specification</strong> (versioned URL or a formal standards track), citable at field level.</li><li><strong>An independent problem boundary</strong>: no overlap with the existing canonical chapters (MCP / A2A / ACP / AG-UI / A2UI-MCP Apps), with a clear &quot;this solves what others do not&quot;.</li><li><strong>A runnable fixture</strong>: zero API keys, deterministic, reproducible from a clean checkout.</li><li><strong>A documented security model</strong>: authn/authz/injection defenses described at spec level, not blog-slogan level.</li><li><strong>A verifiable maintenance path</strong>: governance body, change process, and deprecation policy that can be checked.</li></ol><h3 id="three-iron-rules" tabindex="-1">Three iron rules <a class="header-anchor" href="#three-iron-rules" aria-label="Permalink to &quot;Three iron rules&quot;">​</a></h3><ul><li><strong>discovery ≠ trust ≠ authorization</strong>: discovery mechanisms (ARD, registries, directories, ANS) only answer &quot;can I find it&quot;; identity trust lives in the signature/identity layer (JWS on A2A Cards, DID, ANS&#39;s PKI designs); permission to act lives in the authorization layer (OAuth, permission models). No layer substitutes for another.</li><li><strong>Same name ≠ same thing</strong>: ACP alone has at least four meanings (<a href="./acp-agent-client.html">Agent Client Protocol</a> / the historical IBM ACP / AGNTCY&#39;s Agent Connect Protocol / OpenClaw&#39;s private one); ADL and OAP each have multiple same-name competitors (see cards). Always cite full name + canonical URL.</li><li><strong>Snapshots expire</strong>: IETF Internet-Drafts expire in six months; Candidate/Proposal statuses change at will. Every claim here carries a retrievedAt — recheck before citing.</li></ul><h2 id="_2-observation-cards-discovery-and-directory" tabindex="-1">2. Observation cards: discovery and directory <a class="header-anchor" href="#_2-observation-cards-discovery-and-directory" aria-label="Permalink to &quot;2. Observation cards: discovery and directory&quot;">​</a></h2><h3 id="ard-—-agentic-resource-discovery" tabindex="-1">ARD — Agentic Resource Discovery <a class="header-anchor" href="#ard-—-agentic-resource-discovery" aria-label="Permalink to &quot;ARD — Agentic Resource Discovery&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: Agentic Resource Discovery Specification; authors Junjie Bu (Google), R.V. Guha (Microsoft), Shaun Smith (Hugging Face).</li><li><strong>canonical</strong>: <a href="https://agenticresourcediscovery.org/spec/" target="_blank" rel="noreferrer">https://agenticresourcediscovery.org/spec/</a></li><li><strong>Status</strong>: v0.91, Status: Proposal, self-dated August 26, 2026 (retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: describing/discovering/searching &quot;agentic resources&quot; (MCP tools, A2A agents, skills, and other callable services) across federated networks; entries are JSON-LD nodes; optional <code>/explore</code> and <code>GET /agents</code> methods plus a URN naming appendix.</li><li><strong>Why on the watchlist</strong>: Proposal status, a v0.x version line, an unfinished trust/signature story for entries; no standalone fixture.</li></ul><h3 id="mcp-registry" tabindex="-1">MCP Registry <a class="header-anchor" href="#mcp-registry" aria-label="Permalink to &quot;MCP Registry&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: Model Context Protocol Registry; the modelcontextprotocol organization (GitHub).</li><li><strong>canonical</strong>: <a href="https://github.com/modelcontextprotocol/registry" target="_blank" rel="noreferrer">https://github.com/modelcontextprotocol/registry</a></li><li><strong>Status</strong>: active repo, &quot;a community driven registry service for Model Context Protocol (MCP) servers&quot; (retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: the community registry for MCP servers — it solves the distribution problem of &quot;where do I find a trustworthy server&quot;, not the server protocol itself.</li><li><strong>Why on the watchlist</strong>: a registry is a service/infrastructure, not a protocol contract; the promotion path is into the discovery section of the <a href="./mcp.html">MCP</a> chapter, not a standalone chapter.</li></ul><h3 id="agntcy-oasf-dir-slim-identity-and-observability" tabindex="-1">AGNTCY (OASF / DIR / SLIM + identity and observability) <a class="header-anchor" href="#agntcy-oasf-dir-slim-identity-and-observability" aria-label="Permalink to &quot;AGNTCY (OASF / DIR / SLIM + identity and observability)&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: AGNTCY (the &quot;Internet of Agents&quot; open-source stack); Linux Foundation via LF Projects, initiated by Outshift (Cisco&#39;s incubation arm).</li><li><strong>canonical</strong>: <a href="https://www.agntcy.org/" target="_blank" rel="noreferrer">https://www.agntcy.org/</a></li><li><strong>Status</strong>: active, multi-language SDKs (Go/Python/.NET/Java/Kotlin and more), Apache-2.0 (retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: <strong>DIR</strong> (Agent Directory Service) — federated agent discovery across frameworks/protocols/registries; <strong>SLIM</strong> — secure network-level messaging between agents; <strong>OASF</strong> — a versioned schema framework for agent/skill descriptions (with skill/domain taxonomies); plus Identity (W3C verifiable-credential badges) and Observability components. Acronym expansions defer to official docs (the homepage does not expand them; unverified).</li><li><strong>Why on the watchlist</strong>: heavy overlap with existing canonicals (description schema vs Agent Card; discovery vs ARD/Registry; messaging vs A2A bindings); an independent problem boundary is yet to be argued.</li></ul><h3 id="the-dns-aid-ans-family-ietf-draft-cluster" tabindex="-1">The DNS-AID / ANS family (IETF draft cluster) <a class="header-anchor" href="#the-dns-aid-ans-family-ietf-draft-cluster" aria-label="Permalink to &quot;The DNS-AID / ANS family (IETF draft cluster)&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: several individually submitted IETF Internet-Drafts, not affiliated with each other.</li><li><strong>canonical</strong> (all under <a href="https://datatracker.ietf.org/" target="_blank" rel="noreferrer">https://datatracker.ietf.org/</a>, retrievedAt 2026-09-01, all &quot;work in progress&quot;): <ul><li><strong>AID</strong>: <code>draft-nemethi-aid-agent-identity-discovery</code> — a <code>_agent.&lt;domain&gt;</code> TXT record as a protocol-agnostic bootstrap (v1.2).</li><li><strong>ANS</strong>: <code>draft-narajala-ans</code> (a DNS-style directory + PKI) and <code>draft-narajala-courtney-ansv2</code> (domain-anchored identity + ACME + a transparency log; Bronze/Silver/Gold tiers).</li><li><strong>DN-ANR</strong>: <code>draft-cui-dns-native-agent-naming-resolution</code> — FQDNs as Agent IDs, resolved via SVCB/HTTPS RRs + DNSSEC.</li><li><strong>AGTP ANS</strong>: <code>draft-hood-agtp-discovery</code> — a DISCOVER method plus a governed name service.</li></ul></li><li><strong>Boundary</strong>: a shared thesis, &quot;DNS for agents&quot; — naming, resolution, endpoint verification; all explicitly disclaim semantic discovery and authorization.</li><li><strong>Why on the watchlist</strong>: all are individual drafts that expire in six months, none in a WG/RFC track yet; several competitors occupy the same slot — wait for convergence.</li></ul><h3 id="adl-oap-agent-definition-and-packaging-a-same-name-contention-zone" tabindex="-1">ADL / OAP (agent definition and packaging, a same-name contention zone) <a class="header-anchor" href="#adl-oap-agent-definition-and-packaging-a-same-name-contention-zone" aria-label="Permalink to &quot;ADL / OAP (agent definition and packaging, a same-name contention zone)&quot;">​</a></h3><ul><li><strong>ADL</strong>: <ul><li><strong>canonical</strong>: <a href="https://datatracker.ietf.org/doc/html/draft-nederveld-adl-02" target="_blank" rel="noreferrer">https://datatracker.ietf.org/doc/html/draft-nederveld-adl-02</a> (individual submission with Standards-Track intent; <code>application/adl+json</code>; a &quot;passport&quot; model; claims conversion into A2A Agent Cards and MCP configurations). retrievedAt 2026-09-01.</li><li>The community has at least two same-name efforts (inference-gateway&#39;s ADL and nextmoca&#39;s ADL, both self-described &quot;OpenAPI for AI Agents&quot;) — same name, different schemas.</li></ul></li><li><strong>OAP</strong>: <ul><li><strong>canonical A</strong>: <a href="http://openagentprotocol.eu/" target="_blank" rel="noreferrer">http://openagentprotocol.eu/</a> (seven planes: identity/discovery/invocation/commercial/governance/accountability/coordination; <code>/.well-known/oap-tool.json</code>; 37 RFC-process drafts). retrievedAt 2026-09-01.</li><li><strong>canonical B</strong>: <a href="https://github.com/open-agentic-protocol/" target="_blank" rel="noreferrer">https://github.com/open-agentic-protocol/</a> (white paper v0.2; an OAPverse registry concept).</li></ul></li><li><strong>Boundary</strong>: <strong>definition/manifest formats</strong> for agents (static description), not communication protocols.</li><li><strong>Why on the watchlist</strong>: multiple same-name drafts/white papers; the relationship to the A2A Agent Card — &quot;generates it&quot; or &quot;replaces it&quot; — has not converged; no independent runtime.</li></ul><h3 id="anp-—-agent-network-protocol" tabindex="-1">ANP — Agent Network Protocol <a class="header-anchor" href="#anp-—-agent-network-protocol" aria-label="Permalink to &quot;ANP — Agent Network Protocol&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: Agent Network Protocol; a community project (agentnetworkprotocol.com), plus an IETF-side <code>draft-song-anp-*</code> draft suite (AIP/AITP/ANS/ADP — P2P datagrams + agent:// URIs + DHT/GossipSub).</li><li><strong>canonical</strong>: <a href="https://www.anp-protocol.com/" target="_blank" rel="noreferrer">https://www.anp-protocol.com/</a> and <a href="https://datatracker.ietf.org/" target="_blank" rel="noreferrer">https://datatracker.ietf.org/</a> (for the drafts)</li><li><strong>Status</strong>: the community site is active (bilingual zh/en); the IETF suite is individual drafts (all retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: a three-layer stack of decentralized identity (W3C DID, <code>did:wba</code>) + meta-protocol negotiation + application protocols, aimed at &quot;an internet of billions of agents&quot;.</li><li><strong>Why on the watchlist</strong>: a competing-architecture contest with A2A&#39;s centralized HTTP model rather than a complement; production adoption unverified; the relationship between the two tracks (community site vs IETF drafts) needs watching.</li></ul><h3 id="ahp-—-agent-host-protocol" tabindex="-1">AHP — Agent Host Protocol <a class="header-anchor" href="#ahp-—-agent-host-protocol" aria-label="Permalink to &quot;AHP — Agent Host Protocol&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: Agent Host Protocol; Microsoft (a GitHub Pages spec site).</li><li><strong>canonical</strong>: <a href="https://microsoft.github.io/agent-host-protocol/specification/overview" target="_blank" rel="noreferrer">https://microsoft.github.io/agent-host-protocol/specification/overview</a></li><li><strong>Status</strong>: <strong>DRAFT</strong> (self-labeled; breaking changes expected) (retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: JSON-RPC 2.0, transport-agnostic, SemVer version negotiation, channeled messages/commands/notifications/actions; the <code>x-</code> prefix is reserved for implementation extensions.</li><li><strong>Why on the watchlist</strong>: DRAFT with breaking changes imminent; how the &quot;host-agent&quot; boundary differs from ACP&#39;s editor-agent boundary is unclear.</li></ul><h2 id="_3-observation-cards-payments-and-commerce" tabindex="-1">3. Observation cards: payments and commerce <a class="header-anchor" href="#_3-observation-cards-payments-and-commerce" aria-label="Permalink to &quot;3. Observation cards: payments and commerce&quot;">​</a></h2><h3 id="ucp-—-universal-commerce-protocol" tabindex="-1">UCP — Universal Commerce Protocol <a class="header-anchor" href="#ucp-—-universal-commerce-protocol" aria-label="Permalink to &quot;UCP — Universal Commerce Protocol&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: Universal Commerce Protocol; an industry coalition (the site lists Google, Shopify, Microsoft, OpenAI, Stripe, Walmart, Booking, and dozens more, retrievedAt 2026-09-01).</li><li><strong>canonical</strong>: <a href="https://ucp.dev/" target="_blank" rel="noreferrer">https://ucp.dev/</a></li><li><strong>Status</strong>: the spec site is live and expanding into lodging and food (&quot;Detailed specifications coming soon&quot;); no version number shown on the homepage.</li><li><strong>Boundary</strong>: the assembly layer for agentic commerce — discovery through checkout; REST/JSON-RPC transports with built-in support for AP2 (payments), A2A, and MCP; OAuth 2.0 account linking.</li><li><strong>Why on the watchlist</strong>: the spec body is not yet public at field level; the boundary between top-level orchestration and UCP/AP2/existing commerce APIs is undocumented.</li></ul><h3 id="ap2-—-agent-payments-protocol" tabindex="-1">AP2 — Agent Payments Protocol <a class="header-anchor" href="#ap2-—-agent-payments-protocol" aria-label="Permalink to &quot;AP2 — Agent Payments Protocol&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: Agent Payments Protocol (the spec page also styles it Agentic Payment Protocol); Google-affiliated (spec site ap2-protocol.org).</li><li><strong>canonical</strong>: <a href="https://ap2-protocol.org/ap2/specification/" target="_blank" rel="noreferrer">https://ap2-protocol.org/ap2/specification/</a></li><li><strong>Status</strong>: v0.2 (retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: a <strong>payment security layer</strong>, not a commerce protocol — Checkout Mandates/Receipts plus linked Payment Mandates/Receipts usable as dispute evidence; a five-role model (Shopping Agent, Credential Provider, Merchant, Merchant Payment Processor, and others); explicitly compatible with UCP, with catalog APIs and the like out of scope.</li><li><strong>Why on the watchlist</strong>: v0.x; the market contest with x402/MPP has not converged; how it chains into A2A&#39;s AUTH_REQUIRED delegation is undocumented.</li></ul><h3 id="x402" tabindex="-1">x402 <a class="header-anchor" href="#x402" aria-label="Permalink to &quot;x402&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: x402; the x402 Foundation (Coinbase origin).</li><li><strong>canonical</strong>: <a href="https://x402.org/" target="_blank" rel="noreferrer">https://x402.org/</a></li><li><strong>Status</strong>: active (the site self-reports 75.41M transactions in the last 30 days — <strong>a site-reported figure, unaudited</strong>, retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: HTTP 402-native payments — a one-line middleware returns 402 for unpaid requests and the client pays and retries; stablecoin on-chain settlement, zero protocol fees, network-agnostic.</li><li><strong>Why on the watchlist</strong>: the crypto-rail dependency (stablecoin-only) sits far from mainstream enterprise finance; no independent audit source for adoption data.</li></ul><h3 id="agentic-commerce-protocol-openai-stripe-also-abbreviated-acp" tabindex="-1">Agentic Commerce Protocol (OpenAI/Stripe; also abbreviated ACP) <a class="header-anchor" href="#agentic-commerce-protocol-openai-stripe-also-abbreviated-acp" aria-label="Permalink to &quot;Agentic Commerce Protocol (OpenAI/Stripe; also abbreviated ACP)&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: Agentic Commerce Protocol; co-founded by OpenAI and Stripe (announced 2025-09-29, Apache 2.0).</li><li><strong>canonical</strong>: <a href="https://developers.openai.com/commerce" target="_blank" rel="noreferrer">https://developers.openai.com/commerce</a> and <a href="https://github.com/agentic-commerce-protocol" target="_blank" rel="noreferrer">https://github.com/agentic-commerce-protocol</a></li><li><strong>Status</strong>: already powering ChatGPT Instant Checkout; the changelog keeps moving (retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: a three-spec set — Product Feed (structured catalog data), Agentic Checkout (in-conversation checkout sessions), and Delegated Payment (delegated payment with Stripe&#39;s Shared Payment Token as the first implementation); the merchant stays the Merchant of Record.</li><li><strong>Why on the watchlist</strong>: the boundary is the &quot;shopping inside ChatGPT&quot; ecosystem rather than general agent collaboration; <strong>the abbreviation collides with the <a href="./acp-agent-client.html">Agent Client Protocol</a></strong> — always cite the full name.</li></ul><h3 id="mpp-—-machine-payments-protocol" tabindex="-1">MPP — Machine Payments Protocol <a class="header-anchor" href="#mpp-—-machine-payments-protocol" aria-label="Permalink to &quot;MPP — Machine Payments Protocol&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: Machine Payments Protocol; co-authored by Stripe and Tempo (launched 2026-03-18).</li><li><strong>canonical</strong>: <a href="https://mpp.dev/" target="_blank" rel="noreferrer">https://mpp.dev/</a> (IETF-side authentication-scheme draft: paymentauth.org)</li><li><strong>Status</strong>: an open standard with 100+ services listed at launch (press reports, retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: the other revival of HTTP 402 — a <code>WWW-Authenticate: Payment</code> challenge / <code>Authorization: Payment</code> credential / <code>Payment-Receipt</code> receipt; charge and session intents; multi-rail (Tempo stablecoins, Stripe SPT cards, the Visa extension, Lightning); core x402 exact-payment flows can be mapped onto its charge intent.</li><li><strong>Why on the watchlist</strong>: a same-topic contest with x402 (both use 402, with different header designs); payment-protocol adoption rides on finance/compliance stacks, not technology alone.</li></ul><h3 id="opensharing" tabindex="-1">OpenSharing <a class="header-anchor" href="#opensharing" aria-label="Permalink to &quot;OpenSharing&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: OpenSharing; a Linux Foundation project (Databricks-initiated, evolving Delta Sharing).</li><li><strong>canonical</strong>: <a href="https://opensharing.io/" target="_blank" rel="noreferrer">https://opensharing.io/</a> (note: <strong>opensharing.org is an unrelated site</strong> — do not confuse them)</li><li><strong>Status</strong>: announced 2026-06-10 (press release + coverage, retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: zero-copy sharing of AI assets (agent skills, models, unstructured data) — credential vending (STS/SAS/OAuth short-lived tokens) lets recipients pull directly from the provider&#39;s storage; the sharing server never sits in the data path.</li><li><strong>Why on the watchlist</strong>: just chartered; the boundaries versus MCP resource distribution and Skills packaging are yet to be documented.</li></ul><h2 id="_4-observation-cards-interaction-and-web" tabindex="-1">4. Observation cards: interaction and web <a class="header-anchor" href="#_4-observation-cards-interaction-and-web" aria-label="Permalink to &quot;4. Observation cards: interaction and web&quot;">​</a></h2><h3 id="webmcp" tabindex="-1">WebMCP <a class="header-anchor" href="#webmcp" aria-label="Permalink to &quot;WebMCP&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: WebMCP; the W3C Web Machine Learning Community Group (Google/Microsoft engineer contributions).</li><li><strong>canonical</strong>: the W3C WebML CG draft (secondary sources point to webmachinelearning.github.io/webmcp; <strong>direct verification failed this round</strong> — w3c.github.io/webmcp is 404, retrievedAt 2026-09-01).</li><li><strong>Status</strong>: a <strong>Draft Community Group Report — not a W3C Standard and not on the standards track</strong>; Chrome origin trial (reported 2026-06, Chrome 149).</li><li><strong>Boundary</strong>: a browser-native API — pages expose JSON-Schema&#39;d tools to in-page agents via <code>document.modelContext.registerTool()</code> (earlier <code>navigator.modelContext</code>); a declarative path annotates HTML forms into tools (that section still marked TODO in the draft). Non-goal: headless/fully autonomous browsing.</li><li><strong>Why on the watchlist</strong>: CG draft + origin-trial stage; the security section is incomplete; with zero cross-browser support it cannot be a product dependency.</li></ul><h3 id="nlip-—-natural-language-interaction-protocol" tabindex="-1">NLIP — Natural Language Interaction Protocol <a class="header-anchor" href="#nlip-—-natural-language-interaction-protocol" aria-label="Permalink to &quot;NLIP — Natural Language Interaction Protocol&quot;">​</a></h3><ul><li><strong>Full name/owner</strong>: Natural Language Interaction Protocol; Ecma International TC56.</li><li><strong>canonical</strong>: <a href="https://ecma-international.org/publications-and-standards/standards/ecma-430/" target="_blank" rel="noreferrer">https://ecma-international.org/publications-and-standards/standards/ecma-430/</a></li><li><strong>Status</strong>: <strong>ECMA-430, a published Ecma Standard</strong> (a formal standard, not a draft; the publication date is not shown on the retrieved page, unverified) (retrievedAt 2026-09-01).</li><li><strong>Boundary</strong>: an application-level communication protocol &quot;between AI Agents, or between a human and an AI agent&quot;; motivation and design philosophy are explicitly out of scope of the standard text.</li><li><strong>Why on the watchlist</strong>: a formal standard with unknown ecosystem adoption (no independent data); its problem boundary overlaps heavily with A2A/ACP — independence unproven.</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><h3 id="four-level-reading-path" tabindex="-1">Four-level reading path <a class="header-anchor" href="#four-level-reading-path" aria-label="Permalink to &quot;Four-level reading path&quot;">​</a></h3><ul><li><strong>Beginner</strong>: look up cards by group on this page as needed (group first, card second) → return to the <a href="./">Protocol Map</a> to reorient.</li><li><strong>Builder</strong>: when a card tempts you, run the threshold self-check first (§1, five items) — especially &quot;can you actually write the zero-key fixture&quot;.</li><li><strong>Operator</strong>: treat this page as a selection exclusion list: before any listed protocol reaches production, add the identity and authorization layers yourself.</li><li><strong>Researcher</strong>: subscribe to the relevant draft mailing lists on IETF datatracker; track the official A2A/MCP/ACP changelogs for convergence signals.</li></ul><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Level</th><th>canonical URL</th><th>Use</th><th>Claims supported</th><th>Next</th></tr></thead><tbody><tr><td>This page&#39;s cards</td><td>mixed L0/L2</td><td>see each card</td><td>quick protocol locating and status</td><td>the claims inside each card (all with retrievedAt)</td><td>click through to canonical to recheck</td></tr><tr><td>IETF Datatracker</td><td>L0</td><td><a href="https://datatracker.ietf.org/" target="_blank" rel="noreferrer">https://datatracker.ietf.org/</a></td><td>draft status and expiry checks</td><td>DNS-AID/ANS, ADL, and the ANP suite are all &quot;work in progress&quot;</td><td>subscribe to mailing lists</td></tr><tr><td>a2a-protocol.org / agentclientprotocol.com</td><td>L0</td><td>see the corresponding canonical chapters</td><td>the convergence frame of reference</td><td>the versioned specs of A2A/ACP</td><td>compare against card gaps</td></tr></tbody></table><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li><strong>Falsification entry point</strong>: every first-hand claim on a card should be findable verbatim at its canonical URL; if not, downgrade it to hearsay and fix the card.</li><li>Open 1: the final converged shape of the discovery layer (ARD / Registry / ANS / DIR) — coexisting complements or one winner; unlikely to settle within 2026.</li><li>Open 2: the payments-layer contest (x402 vs MPP vs AP2+UCP vs Agentic Commerce Protocol) over header design and rails; the real-world interoperability of the MPP↔x402 mapping is unverified.</li><li>Open 3: WebMCP&#39;s W3C trajectory and cross-browser support; NLIP&#39;s actual adoption.</li><li>Open 4: the conversion relationships among AGNTCY OASF, the A2A Agent Card, and ADL (&quot;generates&quot; or &quot;replaces&quot;).</li></ul><p><strong>learn-ai stops here</strong>: observation cards and threshold judgment. <strong>Where to go next</strong>: deep chapters for converged protocols → <a href="./a2a.html">A2A</a> / <a href="./acp-agent-client.html">ACP</a> / <a href="./ag-ui.html">AG-UI</a> / <a href="./a2ui-mcp-apps.html">A2UI and MCP Apps</a>; promotion requests → file an issue on this repo with evidence for the five threshold items.</p>',50)])])}const b=t(n,[["render",i]]);export{f as __pageData,b as default};
